-- PasStar · SQLite schema
-- Static tables (BE2, generated by scripts/preprocess.py, read-only at runtime)

CREATE TABLE products (
  id                    TEXT PRIMARY KEY,          -- Valio product code
  name_en               TEXT NOT NULL,
  name_fi               TEXT,
  name_sv               TEXT,
  brand                 TEXT,
  vendor                TEXT NOT NULL,
  category              TEXT NOT NULL,             -- category code
  sales_unit            TEXT NOT NULL,             -- e.g. KI, ST
  base_unit             TEXT NOT NULL,
  lot_size              REAL NOT NULL,             -- order step (sales units)
  units_json            TEXT NOT NULL,             -- [{unitId, sizeInBaseUnits, gtin}]
  gtin                  TEXT,
  temperature_condition INTEGER,
  min_temp_c            REAL,
  max_temp_c            REAL,
  country               TEXT,                      -- ISO alpha-2
  qty_per_sales_unit    REAL,                      -- how many L or kg per sales unit
  qty_unit              TEXT CHECK (qty_unit IN ('L','kg','pcs')),
  qty_source            TEXT CHECK (qty_source IN ('UNIT_CONVERSIONS','NAME_PARSE','UNKNOWN')),
  case_volume_l         REAL,                      -- case volume (litres), for cold-storage space hints
  deposits_json         TEXT NOT NULL DEFAULT '[]',
  substitutions_json    TEXT NOT NULL DEFAULT '[]',-- official substitutes: ["464440", ...]
  marketing_text_en     TEXT,                      -- untrusted input: display only, never used for ranking
  has_synkka            INTEGER NOT NULL,          -- whether manufacturer data exists
  synkka_updated_at     TEXT,
  delivery_reliability  REAL,                      -- 0–1, L2: only the grade is shown externally
  co2_kg_per_kg         REAL                       -- category average
);

CREATE TABLE categories (
  code    TEXT PRIMARY KEY,
  name_en TEXT,
  name_fi TEXT
);

CREATE TABLE product_allergens (
  product_id  TEXT NOT NULL REFERENCES products(id),
  code        TEXT NOT NULL,                       -- GS1 code, e.g. AM, AN, AP
  status      TEXT NOT NULL CHECK (status IN ('CONTAINS','MAY_CONTAIN','FREE_FROM','UNDECLARED')),
  trust_grade TEXT NOT NULL CHECK (trust_grade IN ('A','B','C','D')),
  PRIMARY KEY (product_id, code)
);

CREATE TABLE product_claims (
  product_id TEXT NOT NULL REFERENCES products(id),
  claim      TEXT NOT NULL,                        -- e.g. FREE_FROM_LACTOSE, VEGAN
  source     TEXT NOT NULL CHECK (source IN ('STRUCTURED','NAME_ONLY')),
  PRIMARY KEY (product_id, claim)
);

CREATE TABLE product_labels (
  product_id TEXT NOT NULL REFERENCES products(id),
  label      TEXT NOT NULL,                        -- e.g. EU_ORGANIC_FARMING, SVANEN
  PRIMARY KEY (product_id, label)
);

CREATE TABLE product_flags (
  product_id TEXT NOT NULL REFERENCES products(id),
  flag       TEXT NOT NULL,                        -- e.g. NAME_CLAIM_CONFLICT, NO_SYNKKA, VOLUME_UNKNOWN
  detail     TEXT,
  PRIMARY KEY (product_id, flag)
);

CREATE VIRTUAL TABLE products_fts USING fts5(id UNINDEXED, name_en, name_fi, name_sv, brand);

CREATE INDEX idx_products_category ON products(category);
CREATE INDEX idx_claims_claim ON product_claims(claim);

-- Business tables

-- BE1
CREATE TABLE buyers (
  id               TEXT PRIMARY KEY,
  name             TEXT NOT NULL,
  delivery_address TEXT
);

CREATE TABLE users (                              -- demo users; production would use real login
  id        TEXT PRIMARY KEY,
  org       TEXT NOT NULL CHECK (org IN ('BUYER','VALIO')),
  buyer_id  TEXT REFERENCES buyers(id),          -- required when org = BUYER
  name      TEXT NOT NULL,
  role      TEXT NOT NULL CHECK (role IN ('REQUESTER','APPROVER','OWNER','VALIO_REVIEWER'))
);

CREATE TABLE agents (
  id           TEXT PRIMARY KEY,
  buyer_id     TEXT NOT NULL REFERENCES buyers(id),
  name         TEXT NOT NULL,
  api_key_hash TEXT NOT NULL,
  public_key   TEXT,
  status       TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','BLOCKED'))
);

-- How each agent connects, and its key's lifecycle. The key itself is only ever stored as agents.api_key_hash;
-- key_hint is its first characters, so people can recognise which key an assistant was given.
CREATE TABLE agent_connections (
  agent_id      TEXT PRIMARY KEY REFERENCES agents(id),
  kind          TEXT NOT NULL CHECK (kind IN ('CHATGPT','CLAUDE','ERP','UNKNOWN')),
  key_hint      TEXT,                                 -- NULL: no key issued, or revoked
  key_issued_at TEXT,
  last_used_at  TEXT
);

CREATE TABLE protocols (
  id                 TEXT PRIMARY KEY,
  buyer_id           TEXT NOT NULL REFERENCES buyers(id),
  agent_id           TEXT NOT NULL REFERENCES agents(id),
  version            INTEGER NOT NULL DEFAULT 1,
  status             TEXT NOT NULL CHECK (status IN ('DRAFT','PENDING_BUYER_SIGNATURE','PENDING_VALIO_CONFIRMATION','ACTIVE','REVOKED','EXPIRED','SUPERSEDED')),
  body_json          TEXT NOT NULL,                -- ProtocolBody
  open_questions_json TEXT NOT NULL DEFAULT '[]',
  jws                TEXT,                         -- signature once in effect
  supersedes         TEXT REFERENCES protocols(id),
  created_at         TEXT NOT NULL,
  buyer_signed_at    TEXT,
  valio_confirmed_at TEXT
);

-- BE3
CREATE TABLE profiles (
  id         TEXT PRIMARY KEY,
  buyer_id   TEXT NOT NULL REFERENCES buyers(id),
  name       TEXT NOT NULL,
  body_json  TEXT NOT NULL,                        -- ProfileBody
  updated_at TEXT NOT NULL
);

CREATE TABLE requests (
  id              TEXT PRIMARY KEY,
  buyer_id        TEXT NOT NULL REFERENCES buyers(id),
  protocol_id     TEXT NOT NULL REFERENCES protocols(id),
  profile_id      TEXT REFERENCES profiles(id),
  created_by      TEXT NOT NULL REFERENCES users(id),   -- whoever made the request; cannot approve their own order in SEPARATE mode
  input_mode      TEXT NOT NULL CHECK (input_mode IN ('NATURAL_LANGUAGE','PANEL')),
  raw_text        TEXT,
  structured_json TEXT NOT NULL,                   -- StructuredRequest (after confirmation)
  status          TEXT NOT NULL CHECK (status IN ('CANDIDATES_READY','NO_CANDIDATES','QUOTED','ORDERED','CLOSED')),
  current_attempt INTEGER NOT NULL DEFAULT 1,
  created_at      TEXT NOT NULL
);

CREATE TABLE chain_nodes (
  id              TEXT PRIMARY KEY,
  request_id      TEXT NOT NULL REFERENCES requests(id),
  node            INTEGER NOT NULL CHECK (node BETWEEN 1 AND 4),
  attempt         INTEGER NOT NULL,
  status          TEXT NOT NULL CHECK (status IN ('OK','REJECTED','SUPERSEDED')),
  summary         TEXT NOT NULL,                   -- one sentence the user can understand
  timeline_json   TEXT NOT NULL,                   -- [ChainEvent]
  constraints_json TEXT NOT NULL DEFAULT '[]',     -- constraints added after the user rejects a step
  reject_reason   TEXT,
  created_at      TEXT NOT NULL
);

CREATE TABLE candidates (
  id              TEXT PRIMARY KEY,
  request_id      TEXT NOT NULL REFERENCES requests(id),
  attempt         INTEGER NOT NULL,
  rank            INTEGER,                         -- 1–8; NULL for blocked ones
  badge           TEXT CHECK (badge IN ('RECOMMENDED','CHEAPEST','MOST_RELIABLE')),
  selectable      INTEGER NOT NULL,                -- 0 for violations
  body_json       TEXT NOT NULL                    -- Candidate (including the card)
);

-- BE1
CREATE TABLE quotes (
  id           TEXT PRIMARY KEY,
  request_id   TEXT NOT NULL REFERENCES requests(id),
  candidate_id TEXT NOT NULL REFERENCES candidates(id),
  body_json    TEXT NOT NULL,                      -- QuoteBody
  jws          TEXT NOT NULL,
  valid_until  TEXT NOT NULL,
  status       TEXT NOT NULL CHECK (status IN ('VALID','EXPIRED','SUPERSEDED','USED')),
  created_at   TEXT NOT NULL
);

CREATE TABLE orders (
  id              TEXT PRIMARY KEY,
  request_id      TEXT NOT NULL REFERENCES requests(id),
  quote_id        TEXT NOT NULL REFERENCES quotes(id),
  idempotency_key TEXT NOT NULL UNIQUE,
  status          TEXT NOT NULL CHECK (status IN ('PLACED','PENDING_BUYER_APPROVAL','PENDING_VALIO_REVIEW','REQUOTE_REQUIRED','REJECTED','CANCELLED')),
  gate_json       TEXT NOT NULL,                   -- GateDecision
  created_at      TEXT NOT NULL,
  placed_at       TEXT
);

CREATE TABLE approvals (
  id           TEXT PRIMARY KEY,
  order_id     TEXT REFERENCES orders(id),
  protocol_id  TEXT REFERENCES protocols(id),      -- approval of a protocol change
  kind         TEXT NOT NULL CHECK (kind IN ('BUYER','VALIO')),
  subject      TEXT NOT NULL CHECK (subject IN ('ORDER','PROTOCOL_CHANGE','DATA_ACCESS')),
  reason_codes_json TEXT NOT NULL,
  risk_tags_json    TEXT NOT NULL DEFAULT '[]',
  status       TEXT NOT NULL CHECK (status IN ('PENDING','APPROVED','APPROVED_WITH_CHANGES','REJECTED','ROUTED')),
  decided_by   TEXT,
  decided_at   TEXT,
  note         TEXT,
  created_at   TEXT NOT NULL
);

CREATE TABLE audit_log (
  seq        INTEGER PRIMARY KEY AUTOINCREMENT,
  at         TEXT NOT NULL,
  request_id TEXT,
  actor      TEXT NOT NULL,                        -- agent:<id> | user:<role> | system
  event      TEXT NOT NULL,                        -- e.g. QUOTE_CREATED, GATE_DECIDED
  visibility TEXT NOT NULL CHECK (visibility IN ('BUYER','VALIO','BOTH')),
  payload_json TEXT NOT NULL,
  prev_hash  TEXT NOT NULL,
  hash       TEXT NOT NULL,
  buyer_id    TEXT,                                -- whose data this is; NULL for events with no buyer
  agent_id    TEXT,                                -- which agent triggered it, if any
  reason_code TEXT                                 -- why it was held (gate rule id, Violation.rule or error code)
);

CREATE INDEX idx_audit_holds ON audit_log(event, buyer_id, at);

-- BE2
CREATE TABLE disclosures (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  at          TEXT NOT NULL,
  agent_id    TEXT NOT NULL,
  request_id  TEXT,
  product_id  TEXT,
  field       TEXT NOT NULL,
  sensitivity TEXT NOT NULL CHECK (sensitivity IN ('L0','L1','L2','L3'))
);

CREATE TABLE availability_probes (
  agent_id   TEXT NOT NULL,
  product_id TEXT NOT NULL,
  quantity   REAL NOT NULL,
  at         TEXT NOT NULL
);

CREATE TABLE faults (
  name        TEXT PRIMARY KEY CHECK (name IN ('PRICE_CHANGE','PARTIAL_STOCK','TIMEOUT','RATE_LIMIT','EMPTY_RESULT')),
  enabled     INTEGER NOT NULL DEFAULT 0,
  params_json TEXT NOT NULL DEFAULT '{}'
);
